fn decrement_run(tape: &mut Vec<BlockSymbol>, run_type: RunSymbolType) {
    use BlockSymbol::*;
    match tape.last_mut() {
        Some(Run(t, 1)) if *t == run_type => {
            tape.pop();
        }
        Some(Run(t, n @ 2..)) if *t == run_type => *n -= 1,
        _ => unreachable!("expected at least one of run symbol"),
    }
}
