type Exp = u128;
type BigInt = bnum::BUint<4>;

struct BlockSimulator {
    pub left_tape: Vec<BlockSymbol>,
    pub right_tape: Vec<BlockSymbol>,
    pub state: HigherState,
    pub base_steps: BigInt,
    pub self_steps: u64,
    do_strides: bool,
    do_bicycle: bool,
}

impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use colored::Colorize;
        use BlockSymbol::*;
        let s0 = match *self {
            Run(t, _) => &format!("{:?}", t),
            _ => &format!("{:?}", self),
        };
        let s1 = match *self {
            C0 | C1 => s0.cyan().bold(),
            F1 | F2 | F3 | F4 | F5 | F6 | F7 => s0.blue(),
            C => s0.green().bold(),
            L => s0.dimmed(),
            _ => s0.clone().into(),
        };
        let s_exp = match *self {
            Run(_, n) => if n == 1 { "" } else { &format!("^{}", n) }
            _ => "",
        };
        write!(f, "{}{}", s1, s_exp)
    }
}

